use crate::shape::path::Point;

/// Check if two points are approximately equal.
pub(super) fn points_equal(a: &Point, b: &Point) -> bool {
    const EPSILON: f64 = 1e-10;
    (a.x - b.x).abs() < EPSILON && (a.y - b.y).abs() < EPSILON
}

pub(super) fn upsample_axis_values(
    values: &[f64],
    factor: usize,
    new_len: usize,
    log_space: bool,
) -> Vec<f64> {
    let mut result = Vec::with_capacity(new_len);
    for i in 0..new_len {
        let source = i as f64 / factor as f64;
        let idx = (source.floor() as usize).min(values.len().saturating_sub(2));
        let t = source - idx as f64;
        let v0 = values[idx];
        let v1 = values.get(idx + 1).copied().unwrap_or(v0);
        result.push(interpolate_axis_value(v0, v1, t, log_space));
    }
    result
}

pub(super) fn interpolate_axis_value(v0: f64, v1: f64, t: f64, log_space: bool) -> f64 {
    if log_space && v0 > 0.0 && v1 > 0.0 {
        (v0.ln() + (v1.ln() - v0.ln()) * t).exp()
    } else {
        v0 + (v1 - v0) * t
    }
}
